export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Vector3 } = ctx.THREE;

  const group = new Group();
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Plane geometry for the card label
  const planeGeom = new PlaneGeometry(2.8, 0.5);

  // Create material with gradient and noise for engineered aesthetic
  const colorInk = color(0x16161d);
  const colorPaper = color(0xe8ecf2);
  const colorAccent = color(0xff2a38);
  const colorSurface = color(0x0b0b10);

  // Vertical gradient node: surface (bottom) to ink (top)
  const gradientNode = mx_noise_float(uv().mul(2.0)).mul(0.08).add(
    uv().y.mix(colorSurface, colorInk)
  );

  const mat = new MeshBasicNodeMaterial();
  mat.colorNode = colorSurface.mix(colorInk, uv().y.mul(0.4).add(0.3));

  const planeMesh = new Mesh(planeGeom, mat);
  group.add(planeMesh);

  // Text: "Pricing 1" at 39px (headline role, serif display)
  // Map 39px to scene units: 39px / 100 ≈ 0.39 scene units for display serif at standard scale
  const textObj = ctx.fontAtlas.createText('Pricing 1', {
    fontSize: 39,
    color: 0xe8ecf2,
    align: 'left'
  });
  textObj.position.set(-1.3, 0, 0.01);
  group.add(textObj);

  // Cleanup
  group.userData.cleanup = () => {
    planeGeom.dispose();
    mat.dispose();
    gsap.killTweensOf(group);
  };

  return group;
